/// <summary>
/// CB167_PerformStockReservation.
/// This is a UI builder class for sales order guide check.
/// </summary>
class METSalesOrderGuideCheckUIBuilder extends SysOperationAutomaticUIBuilder
{
    private METSalesOrderGuideCheckContract contract;
    private DialogField                     salesIdDialogField;

}

Method.Source:
/// <summary>
/// Overrides the method to add custom logic.
/// </summary>
public void postBuild()
{
    super();

    contract = this.dataContractObject();

    salesIdDialogField = this.bindInfo().getDialogField(contract, methodStr(METSalesOrderGuideCheckContract, parmSalesId));
    salesIdDialogField.registerOverrideMethod(methodstr(FormStringControl, lookup), methodstr(METSalesOrderGuideCheckUIBuilder, lookupSalesId), this);
}

/// <summary>
/// Constructs lookup againt Sales Id.
/// </summary>
/// <param name = "_control">
/// <c>FormStringControl</c>.
/// </param>
private void lookupSalesId(FormStringControl _control)
{
    Query                query;
    QueryBuildDataSource qbdsSalesLine, 
                         qbdsMetSalesLine;
    SysTableLookup       sysTableLookup;

    query = new Query();
    qbdsSalesLine = query.addDataSource(tableNum(SalesLine));

    qbdsSalesLine.addGroupByField(fieldNum(SalesLine, SalesId));
    qbdsSalesLine.addRange(fieldNum(SalesLine, SalesStatus)).value(enum2Str(SalesStatus::Backorder));

    qbdsMetSalesLine = qbdsSalesLine.addDataSource(tableNum(METSalesLine));

    qbdsMetSalesLine.joinMode(JoinMode::ExistsJoin);
    qbdsMetSalesLine.relations(true);
    qbdsMetSalesLine.addRange(fieldNum(METSalesLine, ReasonId)).value(strFmt('((%1.%2 == "%3") || (%1.%2 == "%4"))',
                                                                      qbdsMetSalesLine.name(),
                                                                      fieldStr(METSalesLine, ReasonId),
                                                                      METConstants::NIRReasonCode, 
                                                                      METConstants::NewReasonCode));

    sysTableLookup = SysTableLookup::newParameters(tableNum(SalesLine), _control);

    sysTableLookup.addLookupField(fieldNum(SalesLine, SalesId), true);
    sysTableLookup.parmQuery(query);
    sysTableLookup.performFormLookup();
}
